window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2f78d8fa1acc5d9d"]={"versions": [{"id": "FIG-2f78d8fa1acc5d9d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR ECUC-Metamodell-Diagramm (UML-Klassendiagramm für BSW-Parameterkonfiguration) kombiniert mit einer tabellarischen Containerspezifikation.\n</li><li><strong>Architektur-Kontext:</strong> BSW-Modul <code>CanTSyn</code> (<em>Time Synchronization over CAN</em>, Communication Stack / System Services).\n</li><li><strong>Funktionaler Zweck:</strong> Statische Parametrierung der Data-ID-Tabelle (<code>CanTSynGlobalTimeOfnsDataIDList</code>) für OFNS-Nachrichten (<em>Offset Follow-Up Message</em>). Die Tabelle dient der Absicherung der Botschaftsintegrität und Authentizität via CRC-Berechnung über 16 diskrete Zählerzustände.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hierarchischer Aufbau (Kompositionen):</strong>\n<ul class=\"fig-list\"><li><code>CanTSyn: EcucModuleDef</code> [0..1]: Wurzel-Moduldeklaration des CAN-Time-Sync-Treibers.\n</li><li><code>CanTSynGlobalTimeDomain: EcucParamConfContainerDef</code> [1..\\*]: Repräsentiert eine CAN-spezifische globale Zeitdomäne (Time Domain).\n</li><li><code>CanTSynGlobalTimeOfnsDataIDList: EcucParamConfContainerDef</code> [0..1]: Optionaler Sub-Container je Zeitdomäne zur Definition der Data-ID-Liste für Offset-Follow-Up-Nachrichten.\n</li><li><code>CanTSynGlobalTimeOfnsDataIDListElement: EcucParamConfContainerDef</code> [16..16]: Exakt 16 Elemente umfassender Sub-Container. Feste Kardinalität korrespondiert mit dem 4-Bit Sequence Counter (2^4 = 16).\n</li></ul>\n</li><li><strong>Konfigurationsparameter:</strong>\n<ul class=\"fig-list\"><li><code>CanTSynGlobalTimeOfnsDataIDListIndex: EcucIntegerParamDef</code> [1..1]: Indexwert des Listenelements; Wertebereich <code>[0 .. 15]</code>.\n</li><li><code>CanTSynGlobalTimeOfnsDataIDListValue: EcucIntegerParamDef</code> [1..1]: Eigentliche 8-Bit Data-ID (<code>uint8</code>); Wertebereich <code>[0 .. 255]</code>.\n</li></ul>\n</li><li><strong>Varianten-Klassifikation:</strong>\n<ul class=\"fig-list\"><li><code>Post-Build Variant Multiplicity: true</code>.\n</li><li><code>Multiplicity Configuration Class</code>: Ausschließlich <code>Pre-compile time</code> (X) für alle Varianten; weder Link-Time- noch Post-Build-Time-Variabilität für die Elementanzahl.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Konfigurationsmodell handelt, determiniert es die Laufzeit-Kryptographie/Prüfsummenbildung:</p>\n<ol class=\"fig-list\"><li><strong>TX-Pfad (Master/Gateway):</strong>\n<ul class=\"fig-list\"><li>Vor dem Senden einer OFNS-PDU liest <code>CanTSyn</code> den aktuellen 4-Bit-Sequenzzähler (<code>SC</code>, 0–15).\n</li><li>Der Zählerwert dient als direkter Lookup-Index auf <code>CanTSynGlobalTimeOfnsDataIDListElement</code> mit übereinstimmendem <code>CanTSynGlobalTimeOfnsDataIDListIndex</code>.\n</li><li>Der zugehörige <code>CanTSynGlobalTimeOfnsDataIDListValue</code> wird als zusätzliches Datum in die CRC-Berechnung (z. B. CRC-8) über die OFNS-Payload einbezogen.\n</li></ul>\n</li><li><strong>RX-Pfad (Slave):</strong>\n<ul class=\"fig-list\"><li>Beim Empfang der OFNS-PDU wird der 4-Bit-Sequenzzähler aus dem Header extrahiert.\n</li><li>Der Slave ruft die identische Data-ID aus seiner lokalen Tabelle ab und validiert die übertragene CRC.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Mismatch der CRC führt zum Verwerfen der OFNS-Nachricht (Schutz vor Replay-Attacken, PDU-Verwechslung und Payload-Korruption).\n</li><li>Fehlgeschlagene Synchronisation triggert Fehlerbehandlung im <code>StbM</code> (<em>Synchronized Time-Base Manager</em>); je nach Konfiguration Meldung an DET/DEM.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Generiert typischerweise ein flaches ROM/Flash-Array im Pre-Compile-Schritt:  \n <code>static const uint8 CanTSyn_OfnsDataIdList[16] = { ... };</code>\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (Tooling):</strong>\n<ul class=\"fig-list\"><li>Strikt 16 Elemente gefordert (<code>lowerMultiplicity = upperMultiplicity = 16</code>). Fehlen Indizes im Bereich 0–15 oder treten Duplikate auf, muss der Generator mit einem Validierungsfehler abbrechen.\n</li></ul>\n</li><li><strong>Laufzeiteffizienz:</strong>\n<ul class=\"fig-list\"><li>Direkte O(1)-Adressierung via <code>OfnsDataIdList[sc &amp; 0x0F]</code> ohne Such- oder Verzweigungs-Overhead im interrupt-nahen Kontext.\n</li></ul>\n</li><li><strong>Netzwerkweite Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Alle ECUs (Master und Slaves) innerhalb derselben CAN-Time-Domain müssen exakt identische Wertepaare konfigurieren, da asymmetrische Data-IDs zu permanentem CRC-Versagen der Offset-Synchronisation führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-cd4935d008763555", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR ECUC-Metamodell-Diagramm (UML-Klassendiagramm für BSW-Parameterkonfiguration).\n</li><li><strong>Architektur-Kontext:</strong> BSW-Modul <code>CanTSyn</code> (<em>Time Synchronization over CAN</em>, Communication Stack / System Services).\n</li><li><strong>Funktionaler Zweck:</strong> Statische Parametrierung der Data-ID-Tabelle (<code>CanTSynGlobalTimeOfnsDataIDList</code>) für OFNS-Nachrichten (<em>Offset Follow-Up Message</em>). Die Tabelle dient der Absicherung der Botschaftsintegrität und Authentizität via CRC-Berechnung über 16 diskrete Zählerzustände.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hierarchischer Aufbau (Kompositionen):</strong>\n<ul class=\"fig-list\"><li><code>CanTSyn: EcucModuleDef</code> [0..1]: Wurzel-Moduldeklaration des CAN-Time-Sync-Treibers.\n</li><li><code>CanTSynGlobalTimeDomain: EcucParamConfContainerDef</code> [1..\\*]: Repräsentiert eine CAN-spezifische globale Zeitdomäne (Time Domain).\n</li><li><code>CanTSynGlobalTimeOfnsDataIDList: EcucParamConfContainerDef</code> [0..1]: Optionaler Sub-Container je Zeitdomäne zur Definition der Data-ID-Liste für Offset-Follow-Up-Nachrichten.\n</li><li><code>CanTSynGlobalTimeOfnsDataIDListElement: EcucParamConfContainerDef</code> [16..16]: Exakt 16 Elemente umfassender Sub-Container. Feste Kardinalität korrespondiert mit dem 4-Bit Sequence Counter (2^4 = 16).\n</li></ul>\n</li><li><strong>Konfigurationsparameter:</strong>\n<ul class=\"fig-list\"><li><code>CanTSynGlobalTimeOfnsDataIDListIndex: EcucIntegerParamDef</code> [1..1]: Indexwert des Listenelements; Wertebereich <code>[0 .. 15]</code>.\n</li><li><code>CanTSynGlobalTimeOfnsDataIDListValue: EcucIntegerParamDef</code> [1..1]: Eigentliche 8-Bit Data-ID (<code>uint8</code>); Wertebereich <code>[0 .. 255]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Konfigurationsmodell handelt, determiniert es die Laufzeit-Kryptographie/Prüfsummenbildung:</p>\n<ol class=\"fig-list\"><li><strong>TX-Pfad (Master/Gateway):</strong>\n<ul class=\"fig-list\"><li>Vor dem Senden einer OFNS-PDU liest <code>CanTSyn</code> den aktuellen 4-Bit-Sequenzzähler (<code>SC</code>, 0–15).\n</li><li>Der Zählerwert dient als direkter Lookup-Index auf <code>CanTSynGlobalTimeOfnsDataIDListElement</code> mit übereinstimmendem <code>CanTSynGlobalTimeOfnsDataIDListIndex</code>.\n</li><li>Der zugehörige <code>CanTSynGlobalTimeOfnsDataIDListValue</code> wird als zusätzliches Datum in die CRC-Berechnung (z. B. CRC-8) über die OFNS-Payload einbezogen.\n</li></ul>\n</li><li><strong>RX-Pfad (Slave):</strong>\n<ul class=\"fig-list\"><li>Beim Empfang der OFNS-PDU wird der 4-Bit-Sequenzzähler aus dem Header extrahiert.\n</li><li>Der Slave ruft die identische Data-ID aus seiner lokalen Tabelle ab und validiert die übertragene CRC.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Mismatch der CRC führt zum Verwerfen der OFNS-Nachricht (Schutz vor Replay-Attacken, PDU-Verwechslung und Payload-Korruption).\n</li><li>Fehlgeschlagene Synchronisation triggert Fehlerbehandlung im <code>StbM</code> (<em>Synchronized Time-Base Manager</em>); je nach Konfiguration Meldung an DET/DEM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Generiert typischerweise ein flaches ROM/Flash-Array im Pre-Compile-Schritt:  \n <code>static const uint8 CanTSyn_OfnsDataIdList[16] = { ... };</code>\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (Tooling):</strong>\n<ul class=\"fig-list\"><li>Strikt 16 Elemente gefordert (<code>lowerMultiplicity = upperMultiplicity = 16</code>). Fehlen Indizes im Bereich 0–15 oder treten Duplikate auf, muss der Generator mit einem Validierungsfehler abbrechen.\n</li></ul>\n</li><li><strong>Laufzeiteffizienz:</strong>\n<ul class=\"fig-list\"><li>Direkte O(1)-Adressierung via <code>OfnsDataIdList[sc &amp; 0x0F]</code> ohne Such- oder Verzweigungs-Overhead im interrupt-nahen Kontext.\n</li></ul>\n</li><li><strong>Netzwerkweite Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Alle ECUs (Master und Slaves) innerhalb derselben CAN-Time-Domain müssen exakt identische Wertepaare konfigurieren, da asymmetrische Data-IDs zu permanentem CRC-Versagen der Offset-Synchronisation führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-d105c69379fcb026", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR ECUC-Metamodell-Diagramm (UML-Klassendiagramm für BSW-Parameterkonfiguration).\n</li><li><strong>Architektur-Kontext:</strong> BSW-Modul <code>CanTSyn</code> (<em>Time Synchronization over CAN</em>, Communication Stack / System Services).\n</li><li><strong>Funktionaler Zweck:</strong> Statische Parametrierung der Data-ID-Tabelle (<code>CanTSynGlobalTimeOfnsDataIDList</code>) für OFNS-Nachrichten (<em>Offset Follow-Up Message</em>). Die Tabelle dient der Absicherung der Botschaftsintegrität und Authentizität via CRC-Berechnung über 16 diskrete Zählerzustände.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hierarchischer Aufbau (Kompositionen):</strong>\n<ul class=\"fig-list\"><li><code>CanTSyn: EcucModuleDef</code> [0..1]: Wurzel-Moduldeklaration des CAN-Time-Sync-Treibers.\n</li><li><code>CanTSynGlobalTimeDomain: EcucParamConfContainerDef</code> [1..\\*]: Repräsentiert eine CAN-spezifische globale Zeitdomäne (Time Domain).\n</li><li><code>CanTSynGlobalTimeOfnsDataIDList: EcucParamConfContainerDef</code> [0..1]: Optionaler Sub-Container je Zeitdomäne zur Definition der Data-ID-Liste für Offset-Follow-Up-Nachrichten.\n</li><li><code>CanTSynGlobalTimeOfnsDataIDListElement: EcucParamConfContainerDef</code> [16..16]: Exakt 16 Elemente umfassender Sub-Container. Feste Kardinalität korrespondiert mit dem 4-Bit Sequence Counter (2^4 = 16).\n</li></ul>\n</li><li><strong>Konfigurationsparameter:</strong>\n<ul class=\"fig-list\"><li><code>CanTSynGlobalTimeOfnsDataIDListIndex: EcucIntegerParamDef</code> [1..1]: Indexwert des Listenelements; Wertebereich <code>[0 .. 15]</code>.\n</li><li><code>CanTSynGlobalTimeOfnsDataIDListValue: EcucIntegerParamDef</code> [1..1]: Eigentliche 8-Bit Data-ID (<code>uint8</code>); Wertebereich <code>[0 .. 255]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Konfigurationsmodell handelt, determiniert es die Laufzeit-Kryptographie/Prüfsummenbildung:</p>\n<ol class=\"fig-list\"><li><strong>TX-Pfad (Master/Gateway):</strong>\n<ul class=\"fig-list\"><li>Vor dem Senden einer OFNS-PDU liest <code>CanTSyn</code> den aktuellen 4-Bit-Sequenzzähler (<code>SC</code>, 0–15).\n</li><li>Der Zählerwert dient als direkter Lookup-Index auf <code>CanTSynGlobalTimeOfnsDataIDListElement</code> mit übereinstimmendem <code>CanTSynGlobalTimeOfnsDataIDListIndex</code>.\n</li><li>Der zugehörige <code>CanTSynGlobalTimeOfnsDataIDListValue</code> wird als zusätzliches Datum in die CRC-Berechnung (z. B. CRC-8) über die OFNS-Payload einbezogen.\n</li></ul>\n</li><li><strong>RX-Pfad (Slave):</strong>\n<ul class=\"fig-list\"><li>Beim Empfang der OFNS-PDU wird der 4-Bit-Sequenzzähler aus dem Header extrahiert.\n</li><li>Der Slave ruft die identische Data-ID aus seiner lokalen Tabelle ab und validiert die übertragene CRC.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Mismatch der CRC führt zum Verwerfen der OFNS-Nachricht (Schutz vor Replay-Attacken, PDU-Verwechslung und Payload-Korruption).\n</li><li>Fehlgeschlagene Synchronisation triggert Fehlerbehandlung im <code>StbM</code> (<em>Synchronized Time-Base Manager</em>); je nach Konfiguration Meldung an DET/DEM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Generiert typischerweise ein flaches ROM/Flash-Array im Pre-Compile-Schritt:  \n <code>static const uint8 CanTSyn_OfnsDataIdList[16] = { ... };</code>\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (Tooling):</strong>\n<ul class=\"fig-list\"><li>Strikt 16 Elemente gefordert (<code>lowerMultiplicity = upperMultiplicity = 16</code>). Fehlen Indizes im Bereich 0–15 oder treten Duplikate auf, muss der Generator mit einem Validierungsfehler abbrechen.\n</li></ul>\n</li><li><strong>Laufzeiteffizienz:</strong>\n<ul class=\"fig-list\"><li>Direkte O(1)-Adressierung via <code>OfnsDataIdList[sc &amp; 0x0F]</code> ohne Such- oder Verzweigungs-Overhead im interrupt-nahen Kontext.\n</li></ul>\n</li><li><strong>Netzwerkweite Konsistenz:</strong>\n<ul class=\"fig-list\"><li>Alle ECUs (Master und Slaves) innerhalb derselben CAN-Time-Domain müssen exakt identische Wertepaare konfigurieren, da asymmetrische Data-IDs zu permanentem CRC-Versagen der Offset-Synchronisation führen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-2f78d8fa1acc5d9d", "to": "FIG-cd4935d008763555", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Entfall der vorangestellten tabellarischen Containerspezifikation (<code>Description</code>, <code>Post-Build Variant Multiplicity</code>, <code>Multiplicity Configuration Class</code>, <code>Included Containers</code>) oberhalb des Klassendiagramms; die Abbildung zeigt ausschließlich das UML-Klassendiagramm.\n</li><li>Das UML-Klassendiagramm mit den Containern <code>CanTSyn</code>, <code>CanTSynGlobalTimeDomain</code>, <code>CanTSynGlobalTimeOfnsDataIDList</code>, <code>CanTSynGlobalTimeOfnsDataIDListElement</code> sowie den Parametern <code>CanTSynGlobalTimeOfnsDataIDListIndex</code> und <code>CanTSynGlobalTimeOfnsDataIDListValue</code> bleibt in Struktur, Multiplizitäten und Wertebereichen unverändert.\n</li></ul>"}, {"from": "FIG-cd4935d008763555", "to": "FIG-d105c69379fcb026", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
